entities = {
    "falcon cloud": "Falcon Cloud is a hosting infrastructure provider.",
}

graph = {"Falcon Cloud": [("supplies", "Acme Corp")]}

def vector_search_entity(query):
    # resolve the starting entity via vector search
    for name in entities:
        if name in query.lower():
            return "Falcon Cloud"
    return None

def graph_traverse(entity):
    # enrich with graph facts for that entity
    return [f"{entity} {rel} {obj}" for rel, obj in graph.get(entity, [])]

def vector_search_chunks(query):
    return ["Falcon Cloud is a hosting infrastructure provider."]

def reciprocal_rank_fusion(ranked_lists, k=60):
    # merge the two ranked result lists
    scores = {}
    for ranked_list in ranked_lists:
        for rank, item in enumerate(ranked_list, start=1):
            scores[item] = scores.get(item, 0) + 1 / (k + rank)
    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

query = "Tell me about Falcon Cloud"
starting_entity = vector_search_entity(query)
graph_facts = graph_traverse(starting_entity)
vector_chunks = vector_search_chunks(query)

fused = reciprocal_rank_fusion([graph_facts, vector_chunks])
print("Hybrid retrieval result:")
for item, score in fused:
    print(f"  {item}: {score:.4f}")
